acao('cob-repasse', (b) => { const [a, c] = aluDe(b);
  const linha = (d = {}) => `<div class="campos" data-dsc style="grid-template-columns:minmax(0,2fr) 130px 42px;align-items:end"><label class="campo"><span>Desconto do proprietário</span><input name="desc" value="${t(d.desc || '')}" placeholder="Ex.: conserto hidráulico"></label><label class="campo"><span>Valor</span><input name="valor" inputmode="decimal" value="${d.valor ? n2(d.valor) : ''}"></label><button type="button" class="bt-ico" style="margin-bottom:14px" data-tira-dsc aria-label="Tirar">${ico('x')}</button></div>`;
  const { el, fechar } = folha({ titulo: `Repasse a ${nomeDe(a.proprietario)}`, corpo: `<div class="linhas-tot"><div><span>Aluguel recebido</span><b>${R$(c.valor + (c.encargo || 0))}</b></div><div><span>Taxa de administração (${n2(a.taxa)}%)</span><b>− ${R$((c.valor + (c.encargo || 0)) * a.taxa / 100)}</b></div></div>${extrasTot(c) ? `<p class="mudo peq" style="margin-top:6px">Condomínio, IPTU e seguro (${R$(extrasTot(c))}) ficam fora do repasse: a imobiliária paga ao condomínio, à prefeitura e à seguradora (está em Contas a pagar).</p>` : ''}<div data-dscs style="margin-top:10px">${(c.descontos || []).map(linha).join('') || linha()}</div><button type="button" class="bt pq" data-mais-dsc>${ico('mais2')}Mais um desconto</button><div class="total-grande"><span>Repasse</span><b data-rep></b></div>`,
    pe: `<button type="button" class="bt" data-fechar>Cancelar</button><button type="button" class="bt cheio" data-ok>${ico('check')}Repassado</button>` });
  const ler = () => $$('[data-dsc]', el).map((r) => ({ desc: $('[name=desc]', r).value.trim(), valor: num($('[name=valor]', r).value) })).filter((x) => x.desc && x.valor > 0);
  const calc = () => { c.descontos = ler(); $('[data-rep]', el).textContent = R$(repasseValor(a, c)); };
  el.addEventListener('input', calc); el.addEventListener('click', (e) => { if (e.target.closest('[data-mais-dsc]')) $('[data-dscs]', el).insertAdjacentHTML('beforeend', linha()); const x = e.target.closest('[data-tira-dsc]'); if (x) { x.closest('[data-dsc]').remove(); calc(); } }); calc();
  $('[data-ok]', el).onclick = () => { calc(); c.repasse = hoje(); grava(); fechar(); toast(`Repasse de ${R$(repasseValor(a, c))} registrado`); };
});
acao('cob-acordo', (b) => { const [a, c] = aluDe(b); editar({ titulo: `Acordo com ${nomeDe(a.inquilino)}`, lista: [{ k: 'ate', r: 'Prometeu pagar até', tipo: 'date', req: true }, { k: 'isenta', r: 'Dispensar multa e juros', tipo: 'check' }, { k: 'obs', r: 'O que foi combinado', largo: true, ph: 'Ex.: paga dia 25, quando recebe o salário' }], v: c.acordo || { ate: somaDias(hoje(), 5) }, salvar: 'Registrar acordo',
  extra: (c.hist || []).length ? `<h3 style="margin:6px 0">Histórico desta cobrança</h3><ul class="lista">${c.hist.map((h) => `<li><div class="tx"><b>${dataBR(h.dia)}</b><small>${t(h.txt)}</small></div></li>`).join('')}</ul>` : '',
  aoSalvar: (d) => { c.acordo = { ...d, feito: hoje() }; histCob(c, `Acordo: paga até ${dataCurta(d.ate)}${d.isenta ? ', sem multa' : ''}${d.obs ? ` · ${d.obs}` : ''}`); grava(); toast('Acordo registrado no histórico'); } }); });
acao('cob-nota', (b) => { const [, c] = aluDe(b); editar({ titulo: 'Anotar contato', lista: [{ k: 'txt', r: 'O que aconteceu', req: true, largo: true, ph: 'Ex.: liguei, disse que paga sexta' }], salvar: 'Anotar', aoSalvar: (d) => { histCob(c, d.txt); grava(); toast('Anotado'); } }); });
acao('cob-zap', (b) => { const [a, c] = aluDe(b); c.cobrado = hoje(); histCob(c, 'Cobrado no WhatsApp'); whatsapp(pessoa(a.inquilino)?.fone, textoCob(a, c), nomeDe(a.inquilino)); });
acao('cob-extrato', (b) => { const [a, c] = aluDe(b); imprimir(`Extrato do proprietário · ${mesAno(c.ref + '-01')}`, `<p><b>Proprietário:</b> ${t(nomeDe(a.proprietario))} · <b>Imóvel:</b> ${t(nomeIm(a.imovel))}</p><table><tbody><tr><td>Aluguel recebido de ${t(nomeDe(a.inquilino))} em ${dataBR(c.pago)}</td><td class="n">${R$(c.valor)}</td></tr>${c.encargo ? `<tr><td>Multa e juros de atraso</td><td class="n">${R$(c.encargo)}</td></tr>` : ''}<tr><td>Taxa de administração (${n2(a.taxa)}%)</td><td class="n">− ${R$((c.valor + (c.encargo || 0)) * a.taxa / 100)}</td></tr>${(c.descontos || []).map((d) => `<tr><td>${t(d.desc)}</td><td class="n">− ${R$(d.valor)}</td></tr>`).join('')}</tbody></table><p class="tot">Repassado em ${dataBR(c.repasse)}: ${R$(repasseValor(a, c))}</p>${extrasTot(c) ? `<p>Também recebidos do inquilino e pagos pela imobiliária: ${Object.entries(c.extras).map(([k, v]) => `${({ condominio: 'condomínio', iptu: 'IPTU', seguro: 'seguro incêndio' })[k]} ${R$(v)}`).join(' · ')}.</p>` : ''}`); });
acao('alu-reajuste', (b) => { const a = db.alugueis.find((x) => x.id === b.dataset.id); const { el } = editar({ titulo: `Reajuste pelo ${a.indice}`, lista: [{ k: 'pct', r: 'Índice acumulado em 12 meses (%)', tipo: 'num', req: true }], aoSalvar: (d) => { (a.reajustes ||= []).push({ dia: hoje(), pct: d.pct, de: a.valor }); a.valor = Math.round(a.valor * (1 + d.pct / 100) * 100) / 100; grava(); toast(`Novo aluguel: ${R$(a.valor)}`); } }); ligarIndice(el, [['pct', a.indice, 12]]); });
acao('alu-novo', (b) => { const livres = db.imoveis.filter((u) => u.fin === 'aluguel' && u.status === 'livre'); if (!livres.length) { toast('Cadastre um imóvel para alugar (livre) antes'); return; } const u0 = im(b.dataset.im) || livres[0];
  const { el } = editar({ titulo: 'Contrato de aluguel', larga: true, lista: [{ k: 'imovel', r: 'Imóvel', tipo: 'select', op: livres.map((u) => [u.id, u.titulo]) }, { k: 'inquilino', r: 'Inquilino', tipo: 'pessoa', req: true }, { k: 'proprietario', r: 'Proprietário', tipo: 'pessoa', req: true }, { k: 'valor', r: 'Aluguel (R$)', tipo: 'money', req: true }, { k: 'diaVenc', r: 'Dia do vencimento', tipo: 'num', req: true },
    { k: 'condominio', r: 'Condomínio (R$/mês)', tipo: 'money', dica: 'Cobrado junto com o aluguel' }, { k: 'iptu', r: 'IPTU (R$/mês)', tipo: 'money' }, { k: 'seguro', r: 'Seguro incêndio (R$/mês)', tipo: 'money' }, { k: 'taxa', r: 'Taxa de administração (%)', tipo: 'num' }, { k: 'inicio', r: 'Início', tipo: 'date', req: true }, { k: 'meses', r: 'Prazo (meses)', tipo: 'num' }, { k: 'indice', r: 'Reajuste anual', tipo: 'select', op: [['IGP-M', 'IGP-M'], ['IPCA', 'IPCA']] }, { k: 'garantia', r: 'Garantia', tipo: 'select', op: ['Seguro-fiança', 'Caução', 'Fiador', 'Título de capitalização'].map((x) => [x, x]) }, { k: 'comissao', r: 'Comissão do corretor (R$)', tipo: 'money', dica: 'Opcional: normalmente parte do 1º aluguel' }, { k: 'corretor', r: 'Corretor', tipo: 'select', op: db.corretores.map((c) => [c.id, c.nome]) }],
    v: { imovel: u0.id, proprietario: u0.proprietario, valor: u0.preco, diaVenc: 10, taxa: 10, inicio: hoje(), meses: 30, indice: 'IGP-M', garantia: 'Seguro-fiança' },
    aoSalvar: (d) => { const a = { id: uid('al'), cobrancas: [], ...d, diaVenc: Math.max(1, Math.min(28, Math.round(d.diaVenc))), meses: Math.round(d.meses) }; delete a.comissao; db.alugueis.unshift(a); im(d.imovel).status = 'alugada'; gerarMes(a, somaMeses(d.inicio, 1).slice(0, 7));
      if (d.comissao > 0) db.comissoes.unshift({ id: uid('cm'), corretor: d.corretor, origem: `Locação · ${nomeIm(d.imovel)}`, valor: d.comissao, dia: hoje(), pago: '' }); grava(); toast('Contrato de aluguel criado'); } });
  $('[name=imovel]', el).onchange = (e) => { const u = im(e.target.value); $('[name=proprietario]', el).value = u.proprietario; $('[name=valor]', el).value = n2(u.preco); };
});
acao('alu-imp', (b) => { const a = db.alugueis.find((x) => x.id === b.dataset.id), q = pessoa(a.inquilino), p = pessoa(a.proprietario);
  imprimir('Contrato de locação residencial', `<p><b>LOCADOR(A):</b> ${t(p?.nome || '')}, representado(a) pela administradora ${t(db.config.nome)}${db.config.creci ? ` (${t(db.config.creci)})` : ''}.</p><p><b>LOCATÁRIO(A):</b> ${t(q?.nome || '')}${q?.doc ? ', CPF ' + t(q.doc) : ''}.</p>
    <p><b>1. Imóvel.</b> ${t(nomeIm(a.imovel))}.</p><p><b>2. Prazo.</b> ${a.meses} meses, a partir de ${dataBR(a.inicio)}.</p><p><b>3. Aluguel.</b> ${R$(a.valor)} por mês, com vencimento todo dia ${a.diaVenc}, reajustado a cada 12 meses pelo ${t(a.indice)}.</p>
    <p><b>4. Garantia.</b> ${t(a.garantia || '')}.</p><p><b>5. Encargos.</b> IPTU, água, luz e condomínio por conta do locatário.</p><p><b>6. Multa.</b> Atraso: 10% de multa e juros de 1% ao mês. Rescisão antes do prazo: multa proporcional de 3 aluguéis (Lei 8.245/91).</p>
    <p>${t(db.config.cidade || '')}, ${dataBR(a.inicio)}.</p><div class="ass"><div>${t(p?.nome || 'Locador')}</div><div>${t(q?.nome || 'Locatário')}</div></div>`, 'Modelo de contrato: revise com o seu advogado antes de assinar.'); });

// ------------------------------------------------------------------ comissões
tela('comissoes', {
  titulo: 'Comissões', ramo: R,
  html() {
    return cab('Comissões de corretor', 'Venda, captação e locação, pagas e a pagar. Captação: quem trouxe o imóvel (no cadastro do imóvel ou do lançamento)', `<button type="button" class="bt" data-acao="cor-ed">${ico('mais2')}Corretor</button><button type="button" class="bt" data-acao="com-nova">${ico('mais2')}Lançar comissão</button>`) +
      `<div class="cartao"><h2>Desempenho nos últimos 30 dias</h2><div class="tab-wrap"><table class="tab empilha compacta"><thead><tr><th>Corretor</th><th class="n">Interessados</th><th class="n">Sem resposta</th><th class="n">Visitas<small style="display:block;font-weight:500">feitas / marcadas</small></th><th class="n">Propostas</th><th class="n">Vendas</th><th class="n">A pagar</th><th class="n">Paga</th></tr></thead><tbody>${db.corretores.map((c) => { const ini = somaDias(hoje(), -30), ls = db.leads.filter((l) => l.corretor === c.id && l.dia >= ini); return `<tr><td data-r="Corretor"><button type="button" class="link-bt" data-acao="cor-ed" data-id="${c.id}" style="background:none;border:0;padding:0;font:inherit;font-weight:700;color:inherit;cursor:pointer;text-align:left" aria-label="Editar ${t(c.nome)}">${t(c.nome)}</button>${(() => { const v = soma(db.comissoes.filter((x) => x.corretor === c.id && !x.pago && /^Captação/.test(x.origem)), (x) => x.valor); return v ? `<small class="mudo" style="display:block;font-weight:400">${R$(v)} de captação a pagar</small>` : ''; })()}</td><td class="n" data-r="Interessados">${ls.length}</td><td class="n ${ls.some(semResposta) ? 'vermelho' : ''}" data-r="Sem resposta">${ls.filter(semResposta).length}</td><td class="n" data-r="Visitas feitas">${db.visitas.filter((v) => v.corretor === c.id && v.status === 'feita' && v.dia >= ini).length} / ${db.visitas.filter((v) => v.corretor === c.id && v.status !== 'feita' && v.dia >= hoje()).length}</td><td class="n" data-r="Propostas">${db.propostas.filter((p) => p.corretor === c.id && p.dia >= ini).length}</td><td class="n" data-r="Vendas">${db.contratos.filter((x) => x.corretor === c.id && x.dia >= ini).length}</td><td class="n" data-r="A pagar">${R$(soma(db.comissoes.filter((x) => x.corretor === c.id && !x.pago), (x) => x.valor))}</td><td class="n" data-r="Paga">${R$(soma(db.comissoes.filter((x) => x.corretor === c.id && x.pago), (x) => x.valor))}</td></tr>`; }).join('')}</tbody></table></div><p class="mudo peq" style="margin-top:8px">Sem resposta: interessado novo há mais de 1 dia sem contato.</p></div>
      <div class="grade g3" style="margin-top:16px">${[].map((c) => { const l = db.comissoes.filter((x) => x.corretor === c.id); return `<div class="cartao"><div class="cartao-cab"><h2>${t(c.nome)}</h2><button type="button" class="bt-ico" data-acao="cor-ed" data-id="${c.id}" aria-label="Editar ${t(c.nome)}">${ico('lapis')}</button></div><p class="mudo peq">CRECI ${t(c.creci)} · ${n2(c.pct)}% nas vendas</p><div class="linhas-tot" style="margin-top:8px"><div><span>A pagar</span><b>${R$(soma(l.filter((x) => !x.pago), (x) => x.valor))}</b></div><div><span>Pago</span><b>${R$(soma(l.filter((x) => x.pago), (x) => x.valor))}</b></div></div></div>`; }).join('')}</div>
      <div class="cartao" style="margin-top:16px"><h2>Lançamentos</h2>${db.comissoes.length ? `<ul class="lista">${db.comissoes.map((x) => `<li><div class="tx"><b>${t(cor(x.corretor)?.nome || '')}</b><small>${t(x.origem)} · ${dataBR(x.dia)}</small></div><div class="val">${R$(x.valor)}</div>${x.pago ? `<span class="et ok">paga ${dataCurta(x.pago)}</span>` : `<button type="button" class="bt pq cheio" data-acao="com-pagar" data-id="${x.id}">Pagar</button>`}</li>`).join('')}</ul>` : vazio('Nenhuma comissão.')}</div>`;
  },
});
acao('com-pagar', (b) => darBaixa(movimentos().find((m) => m.id === 'cm-' + b.dataset.id)));
acao('com-nova', () => editar({ titulo: 'Nova comissão', lista: [{ k: 'corretor', r: 'Corretor', tipo: 'select', op: db.corretores.map((c) => [c.id, c.nome]) }, { k: 'origem', r: 'De quê', req: true, ph: 'Venda ou locação de…' }, { k: 'valor', r: 'Valor (R$)', tipo: 'money', req: true }], aoSalvar: (d) => { db.comissoes.unshift({ id: uid('cm'), dia: hoje(), pago: '', ...d }); grava(); toast('Comissão lançada'); } }));
acao('cor-ed', (b) => { const c = b.dataset.id ? cor(b.dataset.id) : null; editar({ titulo: c ? 'Editar corretor' : 'Novo corretor', lista: [{ k: 'nome', r: 'Nome', req: true }, { k: 'creci', r: 'CRECI' }, { k: 'fone', r: 'WhatsApp', tipo: 'tel' }, { k: 'pct', r: 'Comissão de quem vende (%)', tipo: 'num' }, { k: 'pctCapt', r: 'Comissão de quem captou o imóvel (%)', tipo: 'num', dica: 'Paga a quem trouxe o imóvel, além da comissão de quem vendeu' }], v: c || { pct: 5, pctCapt: 1 },
  aoSalvar: (d) => { if (c) Object.assign(c, d); else db.corretores.push({ id: uid('cr'), ...d }); grava(); toast('Corretor salvo'); }, aoApagar: c ? () => { db.corretores = db.corretores.filter((x) => x !== c); grava(); } : null }); });

// ------------------------------------------------------------------ financeiro (parcelas, aluguéis, repasses e comissões entram sozinhos)
ORIGENS.push(Object.assign(() => [
  ...db.contratos.flatMap((c) => c.parcelas.map((p) => ({ id: 'pa-' + p.id, tipo: 'receber', desc: `${p.tipo} · ${nomeIm(c.imovel)}${!p.pago && p.venc < hoje() ? ' (com multa e juros)' : ''}`, valor: p.valor + (p.pago ? p.encargo || 0 : encargo(p.valor, p.venc, 'venda')), venc: p.venc, pago: p.pago, pessoa: c.comprador, origem: 'Contrato de venda', baixar: (dia) => { p.encargo = encargo(p.valor, p.venc, 'venda', dia); p.pago = dia; } }))).filter((m) => m.pago || m.venc <= somaDias(hoje(), 120)),
  ...db.alugueis.flatMap((a) => a.cobrancas.map((c) => ({ id: 'cb-' + c.id, tipo: 'receber', desc: `Aluguel ${mesAno(c.ref + '-01')} · ${nomeIm(a.imovel)}${!c.pago && c.venc < hoje() ? ' (com multa e juros)' : ''}`, valor: valorCob(c), venc: c.venc, pago: c.pago, pessoa: a.inquilino, origem: 'Aluguel', baixar: (dia) => { c.encargo = c.acordo?.isenta ? 0 : encargo(c.valor, c.venc, 'aluguel', dia); c.pago = dia; if (c.hist?.length || c.acordo) histCob(c, `Pagou ${R$(valorCob(c))}`); } }))),
  ...db.alugueis.flatMap((a) => a.cobrancas.filter((c) => c.pago).map((c) => ({ id: 'rp-' + c.id, tipo: 'pagar', desc: `Repasse ${mesAno(c.ref + '-01')} · ${nomeIm(a.imovel)}`, valor: repasseValor(a, c), venc: somaDias(c.pago, 5), pago: c.repasse, pessoa: a.proprietario, origem: 'Repasse ao proprietário', baixar: (dia) => { c.repasse = dia; } }))),
  ...db.alugueis.flatMap((a) => a.cobrancas.filter((c) => c.pago && extrasTot(c)).map((c) => ({ id: 'ex-' + c.id, tipo: 'pagar', desc: `Condomínio, IPTU e seguro ${mesAno(c.ref + '-01')} · ${nomeIm(a.imovel)}`, valor: extrasTot(c), venc: somaDias(c.pago, 3), pago: c.extrasPago || '', pessoa: '', origem: 'Encargos do aluguel', baixar: (dia) => { c.extrasPago = dia; } }))),
  ...db.comissoes.map((x) => ({ id: 'cm-' + x.id, tipo: 'pagar', desc: `Comissão · ${cor(x.corretor)?.nome || ''} · ${x.origem}`, valor: x.valor, venc: somaDias(x.dia, 10), pago: x.pago, pessoa: '', origem: 'Comissão', baixar: (dia) => { x.pago = dia; } })),
], { ramo: R }));
BUSCAS.push(Object.assign((q) => [
  ...db.imoveis.filter((u) => `${u.titulo} ${u.bairro}`.toLowerCase().includes(q)).slice(0, 8).map((u) => [u.titulo, `${ST[u.status]} · ${R$(u.preco)}`, u.emp ? `emp/${u.emp}` : 'imoveis/avulsos']),
  ...db.emps.filter((e) => e.nome.toLowerCase().includes(q)).map((e) => [e.nome, 'Lançamento', `emp/${e.id}`]),
  ...db.leads.filter((l) => `${l.nome} ${l.fone}`.toLowerCase().includes(q)).map((l) => [l.nome, `Interessado · ${l.interesse}`, 'funil']),
  ...db.corretores.filter((c) => c.nome.toLowerCase().includes(q)).map((c) => [c.nome, 'Corretor', 'comissoes']),
], { ramo: R }));
RELACIONADOS.push((p) => { if (!db.config.ramos.includes(R)) return ''; const ct = db.contratos.filter((c) => c.comprador === p.id), al = db.alugueis.filter((a) => a.inquilino === p.id || a.proprietario === p.id), ims = db.imoveis.filter((u) => u.proprietario === p.id); if (!ct.length && !al.length && !ims.length) return '';
  return `<div class="cartao"><h2>Imóveis e contratos</h2><ul class="lista">${ct.map((c) => `<li><button type="button" class="item-bt" data-ir="contrato/${c.id}"><span class="tx"><b>Comprou: ${t(nomeIm(c.imovel))}</b><small>falta ${R$(saldoContrato(c))}</small></span>${ico('frente')}</button></li>`).join('')}${al.map((a) => `<li><div class="tx"><b>${a.inquilino === p.id ? 'Aluga' : 'Proprietário de'}: ${t(nomeIm(a.imovel))}</b><small>${R$(a.valor)}/mês</small></div></li>`).join('')}${ims.filter((u) => !al.some((a) => a.imovel === u.id)).map((u) => `<li><div class="tx"><b>Proprietário de: ${t(u.titulo)}</b><small>${ST[u.status]}</small></div></li>`).join('')}</ul></div>`; });
